CREATE TABLE q(test,expr); INSERT INTO q VALUES('1','one'),('2','one NEAR/1 five'),('3','t*'),('4','t* NEAR/0 five'),('5','o* NEAR/1 f*'),('6','one NEAR five NEAR two NEAR four NEAR three'),('7','one NEAR xyz'),('8','one OR two'),('9','one AND two'),('10','one NOT two'),('11','one AND two OR three'),('12','three OR one AND two'),('13','(three OR one) AND two'),('14','(three OR one) AND two NOT (five NOT four)'),('15','"one two"'),('16','"one two" NOT "three four"'); CREATE TABLE result AS SELECT test,'ASC' AS direction,(SELECT group_concat(docid,',') FROM (SELECT docid FROM t1 WHERE t1 MATCH q.expr ORDER BY docid ASC)) AS docs FROM q UNION ALL SELECT test,'DESC',(SELECT group_concat(docid,',') FROM (SELECT docid FROM t1 WHERE t1 MATCH q.expr ORDER BY docid DESC)) FROM q;